208	int main(int argc, char* argv[]) {
209	    if (argc < 3) {
210	        print_usage();
211	        return 1;
212	    }
213	
214	    // V36.D: Pre-Build-Permutationen-Check. Wenn KEINE Permutationen
215	    // vorhanden sind, hat das Experiment keinen Sinn -> Fatal mit Exit 2.
216	    if (int rc = comdare::messung_driver::assert_permutations_available_or_die(); rc != 0) { return rc; }
217	
218	    // V37.C (2026-05-23): Manifest-Iteration — pro Permutation ein Eintrag.
219	    {
220	        auto perms = comdare::messung_driver::load_all_permutations();
221	        std::cout << "[V37.C] Permutations-Inventar: " << perms.size() << " Eintraege\n";
222	        std::size_t i{0};
223	        for (auto const& p : perms) {
224	            std::cout << "  [" << (++i) << "/" << perms.size() << "] " << p.subsystem << " :: " << p.id << "\n";
225	        }
226	    }
227	
228	    // V38.C (2026-05-24): Plugin-Loader — laedt alle .dll/.so/.dylib aus
229	    // dem perm-Baum, ruft pro Plugin perm_<id>_run(N, &micros) auf.
230	    // V41.B1 (2026-05-24): jeder Plugin-Aufruf wird als binary measurement-record
231	    // in <output_dir>/measurements/<perm_id>.bin geschrieben (Stage-03-kompatibel).
232	    {
233	        // Annahme: messung_driver-Binary liegt in build/<preset>/<config>/.
234	        // perm-Root liegt unter build/<preset>/perm/.
235	        auto exe_dir = std::filesystem::current_path();
236	        // heuristische Suche nach perm/-Wurzel
237	        auto perm_root = exe_dir / "perm";
238	        for (int up = 0; up < 4 && !std::filesystem::exists(perm_root); ++up) {
239	            exe_dir   = exe_dir.parent_path();
240	            perm_root = exe_dir / "perm";
241	        }
242	        if (!std::filesystem::exists(perm_root)) {
243	            std::cerr << "[V38.C] perm-Root nicht gefunden, ueberspringe Plugin-Mikrobenchmark\n";
244	        } else {
245	            std::cout << "[V38.C] lade Plugins aus: " << perm_root.string() << "\n";
246	            auto                    plugins = comdare::messung_driver::load_all_perm_plugins(perm_root);
247	            constexpr unsigned long kRunOps = 1000;
248	            std::cout << "[V38.C] " << plugins.size() << " Plugins geladen, fuehre Mikrobenchmark aus (N=" << kRunOps
249	                      << ")\n";
250	
251	            // V41.B1: ein Aggregat-File fuer alle Permutationen
252	            std::filesystem::path const v41_out_dir = std::filesystem::path{argv[2]} / "measurements";
253	            std::filesystem::create_directories(v41_out_dir);
254	            comdare::messung_driver::MeasurementWriter writer{v41_out_dir / "all_permutations.bin"};
255	            if (!writer.ok()) {
256	                std::cerr << "[V41.B1] WARN: konnte " << (v41_out_dir / "all_permutations.bin").string()
257	                          << " nicht oeffnen, ueberspringe binary records\n";
258	            }
259	
260	            // V41.B3: pro Plugin N_REPS Runs sammeln (statt 1) fuer Statistik
261	            constexpr std::size_t                           kReps = 10;
262	            std::vector<comdare::messung_driver::PermStats> all_stats;
263	            all_stats.reserve(plugins.size());
264	
265	            // Ladebalken ueber ALLE kartesischen Produkte (CE + prt-art gemeinsam).
266	            ProgressBar bar{"[Mikrobench] Kartesische Achsen-Permutationen", plugins.size()};
267	            for (auto const& p : plugins) {
268	                std::vector<double> samples_us;
269	                samples_us.reserve(kReps);
270	                bool all_ok = true;
271	                for (std::size_t rep = 0; rep < kReps; ++rep) {
272	                    double micros = 0.0;
273	                    int    rc     = p.desc->run(kRunOps, &micros);
274	                    if (rc == 0) {
275	                        samples_us.push_back(micros);
276	                    } else {
277	                        all_ok = false;
278	                    }
279	                }
280	                std::string subsystem = (std::string{p.desc->id}.rfind("pa_", 0) == 0) ? "prt_art" : "cache_engine";
281	                auto        stats     = comdare::messung_driver::compute_stats(p.desc->id, subsystem, p.desc->axes,
282	                                                                               p.desc->version, samples_us);
283	                all_stats.push_back(stats);
284	
285	                bar.tick(stats.permutation_id);
286	                if (!(all_ok && !samples_us.empty())) {
287	                    bar.note(std::string{"[ERR] "} + std::string{p.desc->id} +
288	                             "  ok-samples=" + std::to_string(samples_us.size()));
289	                }
290	
291	                // V41.B1: pro Plugin EIN aggregate binary record (mean us/op)
292	                // V41.P1: workload_used = "micro" (der eingebaute Plugin-Mikrobenchmark; echte
293	                // YCSB-Reihen setzen hier spaeter das Config-Workload-Label).
294	                if (writer.ok() && !samples_us.empty()) {
295	                    auto rec = comdare::messung_driver::make_record_from_run(static_cast<std::uint64_t>(kRunOps),
296	                                                                             stats.mean_us);
297	                    auto fp  = comdare::messung_driver::fingerprint_of(p.desc->id);
298	                    writer.add(p.desc->id, fp, all_ok, "micro", rec);
299	                }
300	            }
301	            bar.finish();
302	            writer.finalize();
303	            if (writer.ok() || writer.count() > 0) {
304	                std::cout << "[V41.B1] " << writer.count() << " binary records geschrieben: " << writer.path().string()
305	                          << "\n";
306	            }
307	
308	            // V41.B3: Stats-CSV + paarweise Welch-Vergleiche
309	            std::filesystem::path stats_csv = v41_out_dir / "permutation_stats.csv";
310	            comdare::messung_driver::write_stats_csv(stats_csv, all_stats);
311	            std::cout << "[V41.B3] " << all_stats.size() << " Stats-Eintraege: " << stats_csv.string() << "\n";
312	
313	            // ─── V41.G.1: Hierarchische Achsen-Iteration + Auswertung ───
314	            namespace md = comdare::messung_driver;
315	            // Item 1: aus (id, axes) jeder Permutation den Achsen-Baum bauen.
316	            std::vector<md::AxisItem> axis_items;
317	            axis_items.reserve(all_stats.size());
318	            for (auto const& s : all_stats) { axis_items.push_back(md::make_axis_item(s.permutation_id, s.axes)); }
319	            auto const axis_keys = md::collect_axis_keys(axis_items);
320	            auto const tree      = md::build_axis_tree(axis_items, axis_keys);
321	
322	            // Item 2: hierarchische Ausgabe — Gruppen-Header je Achsen-Ebene "== key=value ==".
323	            std::cout << "[V41.G.1] Achsen-Baum (" << axis_keys.size() << " Achsen:";
324	            for (auto const& k : axis_keys) std::cout << ' ' << k;
325	            std::cout << "):\n";
326	            std::function<void(md::AxisTreeNode const&, int)> print_node = [&](md::AxisTreeNode const& n, int depth) {
327	                std::string const indent(static_cast<std::size_t>(depth) * 2, ' ');
328	                if (!n.axis_key.empty()) {
329	                    std::cout << indent << "== " << n.axis_key << '=' << n.axis_value << " == ("
330	                              << md::count_leaf_items(n) << " Perm.)\n";
331	                }
332	                for (auto const& c : n.children) print_node(c, depth + 1);
333	                for (auto idx : n.item_indices) {
334	                    std::cout << indent << "  - " << all_stats[idx].permutation_id << "  " << all_stats[idx].mean_us
335	                              << " us/op\n";
336	                }
337	            };
338	            print_node(tree, 0);
339	
340	            // Item 3: per-Achsen-Spalten-CSV (eine Spalte je Achsen-Schlüssel).
341	            std::filesystem::path const per_axis_csv = v41_out_dir / "permutation_stats_per_axis.csv";
342	            md::write_stats_csv_per_axis(per_axis_csv, all_stats, axis_keys);
343	            std::cout << "[V41.G.1] per-Achsen-CSV (" << axis_keys.size()
344	                      << " Achsen-Spalten): " << per_axis_csv.string() << "\n";
345	
346	            // Samples je id für Welch sammeln.
347	            std::map<std::string, std::vector<double>> samples_by_id;
348	            ProgressBar welch_bar{"[Welch-Sampling] Kartesische Achsen-Permutationen", plugins.size()};
349	            for (auto const& p : plugins) {
350	                std::vector<double> samples;
351	                for (std::size_t rep = 0; rep < kReps; ++rep) {
352	                    double micros = 0.0;
353	                    if (p.desc->run(kRunOps, &micros) == 0) samples.push_back(micros);
354	                }
355	                welch_bar.tick(p.desc->id);
356	                samples_by_id[std::string{p.desc->id}] = std::move(samples);
357	            }
358	            welch_bar.finish();
359	
360	            // Item 4: Welch RESTRINGIERT auf Achsen-Subtrees — je variierender Achse nur Items, die in
361	            // ALLEN anderen Achsen übereinstimmen (z.B. gleiche simd+layout, vergleiche Allokator-Varianten).
362	            std::vector<md::PairwiseRow> pairs;
363	            for (auto const& varying : axis_keys) {
364	                auto const groups = md::subtree_groups_varying(axis_items, axis_keys, varying);
365	                for (auto const& g : groups) {
366	                    std::string fixed;
367	                    for (auto const& k : axis_keys) {
368	                        if (k == varying) continue;
369	                        fixed += (fixed.empty() ? "" : ";") + k + "=" +
370	                                 md::axis_value(axis_items[g.front()].axes, k).value_or("<none>");
371	                    }
372	                    for (std::size_t i = 0; i < g.size(); ++i) {
373	                        for (std::size_t j = i + 1; j < g.size(); ++j) {
374	                            auto const& a  = axis_items[g[i]].id;
375	                            auto const& b  = axis_items[g[j]].id;
376	                            auto const& sa = samples_by_id[a];
377	                            auto const& sb = samples_by_id[b];
378	                            if (sa.size() < 2 || sb.size() < 2) continue;
379	                            auto w = md::welch_us(sa, sb);
380	                            if (!w.valid) continue;
381	                            md::PairwiseRow row{};
382	                            row.a               = a;
383	                            row.b               = b;
384	                            row.mean_a          = w.mean_a / 1000.0; // ns->us
385	                            row.mean_b          = w.mean_b / 1000.0;
386	                            row.delta           = row.mean_a - row.mean_b;
387	                            row.t_stat          = w.t_statistic;
388	                            row.df              = w.degrees_of_freedom;
389	                            row.p_value         = w.p_value;
390	                            row.significant_5pc = (w.p_value < 0.05);
391	                            row.varying_axis    = varying;
392	                            row.fixed_context   = fixed;
393	                            pairs.push_back(row);
394	                        }
395	                    }
396	                }
397	            }
398	            std::filesystem::path const pairs_csv = v41_out_dir / "welch_pairwise.csv";
399	            md::write_pairwise_csv(pairs_csv, pairs);
400	            std::size_t sig = 0;
401	            for (auto const& r : pairs)
402	                if (r.significant_5pc) ++sig;
403	            std::cout << "[V41.G.1] " << pairs.size() << " subtree-restringierte Welch-Tests, " << sig
404	                      << " signifikant (p<0.05): " << pairs_csv.string() << "\n";
405	
406	            comdare::messung_driver::unload_all(plugins);
407	        }
408	    }
409	
410	    std::filesystem::path config_dir{argv[1]};
411	    std::filesystem::path output_dir{argv[2]};
412	    std::filesystem::path comdare_root = std::filesystem::current_path();
413	    std::filesystem::path messreihen_xml; // V9.6: optional
414	
415	    for (int i = 3; i < argc; ++i) {
416	        std::string a{argv[i]};
417	        if (a.rfind("--comdare-root=", 0) == 0) {
418	            comdare_root = std::filesystem::path{a.substr(15)};
419	        } else if (a.rfind("--messreihen-xml=", 0) == 0) {
420	            messreihen_xml = std::filesystem::path{a.substr(17)};
421	        } else {
422	            std::cerr << "Unknown arg: " << a << "\n";
423	            print_usage();
424	            return 1;
425	        }
426	    }
427	
428	    std::cout << "==== Comdare Messung-Driver (REV 7.6 V8.12) ====\n";
429	    std::cout << "Config-Dir   : " << config_dir.string() << "\n";
430	    std::cout << "Output-Dir   : " << output_dir.string() << "\n";
431	    std::cout << "Comdare-Root : " << comdare_root.string() << "\n";
432	    std::cout << "Messreihen   : 3 (A=PRT-ART vs SOTA, B=Cache-Engine, C=Merge)\n";
433	
434	    // REV 7.6 V8.12 — Aktivierung des EXPERIMENT_MODE im Sub-Build (User-Direktive
435	    // 2026-05-13/14). Default in cache-engine ist OFF (Production-Pfad).
436	    // Beim Sub-Build der Permutations-Module muss das Flag explizit ON sein,
437	    // damit ResultAggregator + Mess-Hooks in der ExecutionEngine kompiliert werden.
438	#ifndef COMDARE_EXPERIMENT_MODE_ON
439	    std::cerr << "[V8.12] WARNING: COMDARE_EXPERIMENT_MODE_ON ist NICHT definiert.\n"
440	              << "         Der messung_driver wurde ohne Mess-Hooks gebaut.\n"
441	              << "         Build mit: cmake -DCOMDARE_EXPERIMENT_MODE=ON\n";
442	#else
443	    std::cout << "Experiment-Mode: ON (ResultAggregator in ExecutionEngine aktiv)\n";
444	#endif
