93	/// render_sota_module_source — der kompilierbare Modul-.cpp-Quelltext einer SOTA/PRT-ART-Komposition.
94	/// IDENTISCH zum CMake-Codegen-Modul (comdare_codegen_anatomy_module): ABI-Header + Composition-Header +
95	/// COMDARE_DEFINE_ANATOMY_MODULE(<FQ-Typ>). Real-baubar via cl (probe-belegt für alle 6 SOTA + PRT-ART + Stufe3/B).
96	[[nodiscard]] inline std::string render_sota_module_source(std::string const& fq_type, std::string const& header) {
97	    return "// AUTO-GENERATED (STRANG-A Inc5 / S6) SOTA/PRT-ART Modul — DO NOT EDIT\n"
98	           "#define COMDARE_ANATOMY_MODULE_BUILD 1\n"
99	           "#include <cache_engine/abi/anatomy_module_abi_v1.hpp>\n"
100	           "#include <" +
101	           header +
102	           ">\n"
103	           "COMDARE_DEFINE_ANATOMY_MODULE(" +
104	           fq_type + ")\n";
105	}
