111	
112	/// build_sota_series_a_modules — die Reihe-A-Lebewesen (PRT-ART + die 6 KnownReferenceCompositions),
113	/// je als isolierte reale Komposition (Stufe1_CeOnly). binary_id = serialize_composition_from_slots.
114	[[nodiscard]] inline std::vector<SotaModule> build_sota_series_a_modules() {
115	    std::vector<SotaModule> out;
116	    // PRT-ART (Thesis-eigenes Prüfling-Lebewesen, Reihe A isoliert).
117	    out.push_back(SotaModule{"prt_art", sota_binary_id("A", std::string{cmp::PrtArtComposition::name}),
118	                             "::comdare::cache_engine::compositions::PrtArtComposition",
119	                             "compositions/prt_art_reference.hpp"});
120	    // Die 6 SOTA über die zentrale mp_list (Tool-Iteration, known_compositions_list.hpp). Wir nehmen die
121	    // ersten 6 (CE-Reimpl) als die im Profil benannten Lebewesen art/hot/wormhole/surf/masstree/start.
122	    auto add_sota = [&]<class Entry>() {
123	        using C = typename Entry::composition;
124	        std::string const sn{Entry::short_name};
125	        // Nur die 6 Basis-SOTA (kein _pb-PaperBinding in diesem Pilot — die Profil-Namen sind die 6 Basis).
126	        if (sn == "art" || sn == "hot" || sn == "wormhole" || sn == "surf" || sn == "masstree" || sn == "start") {
127	            out.push_back(SotaModule{sn, sota_binary_id("A", std::string{C::name}),
128	                                     std::string{C::cpp_type_name}, // FQ-Typ-Name aus HasCompositionLocation (R5.G)
129	                                     std::string{C::header_include}});
130	        }
131	    };
132	    mp::mp_for_each<cmp::KnownReferenceCompositions>(
133	        [&]<class Entry>(Entry) { add_sota.template operator()<Entry>(); });
134	    return out;
135	}
