38	class DatasetLoaderStrategy {
39	public:
40	    virtual ~DatasetLoaderStrategy() = default;
41	
42	    /// Laedt @p dataset_id und konvertiert in das Operation-Modell.
43	    /// @param dataset_id loader-spezifischer Bezeichner (Pfad, Tabelle, Trace-Name ...)
44	    /// @param seed       Reproduzierbarkeits-Schluessel (falls Shuffle/Sampling noetig)
45	    /// @return Operation-Folge, oder std::nullopt bei Fehler (Aufrufer faellt auf YCSB zurueck).
46	    [[nodiscard]] virtual std::optional<std::vector<wg::Operation>> load(std::string_view dataset_id,
47	                                                                         std::uint64_t    seed) = 0;
48	
49	    /// Optionale Kurzbeschreibung (Quelle, Version) fuer Logs.
50	    [[nodiscard]] virtual std::string metadata() const { return {}; }
