53	/**
54	 * @brief Registry (Meyers-Singleton): Loader registrieren sich unter einem loader_id-Schluessel.
55	 *
56	 * Header-only; loader_id entspricht dem XML-Attribut `dataset_source` (z.B. "sosd", "tpc").
57	 */
58	class DatasetLoaderRegistry {
59	public:
60	    static DatasetLoaderRegistry& instance() {
61	        static DatasetLoaderRegistry registry;
62	        return registry;
63	    }
64	
65	    void register_loader(std::string loader_id, std::unique_ptr<DatasetLoaderStrategy> loader) {
66	        loaders_[std::move(loader_id)] = std::move(loader);
67	    }
68	
69	    [[nodiscard]] bool has(std::string_view loader_id) const {
70	        return loaders_.find(std::string{loader_id}) != loaders_.end();
71	    }
72	
73	    /// Sucht den Loader @p loader_id und delegiert an dessen load().
74	    [[nodiscard]] std::optional<std::vector<wg::Operation>>
75	    try_load(std::string_view loader_id, std::string_view dataset_id, std::uint64_t seed) const {
76	        auto it = loaders_.find(std::string{loader_id});
77	        if (it == loaders_.end() || !it->second) return std::nullopt;
78	        return it->second->load(dataset_id, seed);
79	    }
80	
81	private:
82	    DatasetLoaderRegistry() = default;
83	    std::unordered_map<std::string, std::unique_ptr<DatasetLoaderStrategy>> loaders_;
84	};
