86	/// Mappt einen YCSB-Bezeichner ("YCSB_A".."YCSB_F" oder "A".."F") auf das Enum (Default C).
87	[[nodiscard]] inline wg::YcsbWorkload parse_ycsb_letter(std::string_view s) {
88	    if (s == "YCSB_A" || s == "A") return wg::YcsbWorkload::A;
89	    if (s == "YCSB_B" || s == "B") return wg::YcsbWorkload::B;
90	    if (s == "YCSB_C" || s == "C") return wg::YcsbWorkload::C;
91	    if (s == "YCSB_D" || s == "D") return wg::YcsbWorkload::D;
92	    if (s == "YCSB_E" || s == "E") return wg::YcsbWorkload::E;
93	    if (s == "YCSB_F" || s == "F") return wg::YcsbWorkload::F;
94	    return wg::YcsbWorkload::C;
95	}
