97	/**
98	 * @brief Komfort-Einstieg fuer Phase 5 (siehe README): erst Registry, sonst YCSB-Generator.
99	 *
100	 * @param loader_source XML-`dataset_source` (leer = direkt YCSB-Generator)
101	 * @param dataset_id    XML-`dataset_id` bzw. YCSB-Buchstabe
102	 * @param config        WorkloadConfig (num_keys/num_operations/seed ...)
103	 * @param seed          Reproduzierbarkeits-Schluessel fuer den Loader
104	 * @return Operation-Folge (nie leer im Fehlerfall — Fallback erzeugt YCSB).
105	 */
106	[[nodiscard]] inline std::vector<wg::Operation> load_or_generate_ycsb(std::string_view          loader_source,
107	                                                                      std::string_view          dataset_id,
108	                                                                      wg::WorkloadConfig const& config,
109	                                                                      std::uint64_t             seed) {
110	    if (!loader_source.empty()) {
111	        auto loaded = DatasetLoaderRegistry::instance().try_load(loader_source, dataset_id, seed);
112	        if (loaded && !loaded->empty()) return std::move(*loaded);
113	    }
114	    wg::WorkloadGenerator gen{config};
115	    return gen.generate_ycsb(parse_ycsb_letter(dataset_id));
116	}
